var regex1 = /https?:\/\/files\.iwara\.tv\/file\/([a-zA-Z0-9\-]+)\?.*/;  
var regex2 = /https?:\/\/files\.iwara\.tv\/file\/[a-zA-Z0-9\-]+\?expires=([0-9]+)&hash=[a-zA-Z0-9]+/;  
var match1 = result.match(regex1);
var fileid = match1[1];
var match2 = result.match(regex2);
var expireid = match2[1];
var shakey = '5nFp9kmbNnHdAFhaqMvt';
var mingstr = `${fileid}_${expireid}_${shakey}`;
var mistr = java.digestHex(mingstr,'sha1');
result = result + ",\{\"headers\":\{\"X-Version\":\"" + mistr + "\"\}\}";
</js>

